theorem embedDoubleLaurent_ofDoubleLaurent {x : (R⸨X⸩)⸨X⸩}
    (hout : ∀ n < 0, x.coeff n = 0) (hin : ∀ (n : ℤ), ∀ g < 0, (x.coeff n).coeff g = 0) :
    embedDoubleLaurent (ofDoubleLaurent x) = x

theorem IsUnramified.of_injective (hM : IsUnramified I M) {f : N → M}
    (hf : Function.Injective f) (hf_smul : ∀ (σ : G) (n : N), f (σ • n) = σ • f n) :
    IsUnramified I N

theorem IsUnramified.of_surjective (hM : IsUnramified I M) {f : M → N}
    (hf : Function.Surjective f) (hf_smul : ∀ (σ : G) (m : M), f (σ • m) = σ • f m) :
    IsUnramified I N

theorem equation_xParam_yParam (W : WeierstrassCurve K) [IsIntegral R W] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) (hz0 : z ≠ 0) :
    W.toAffine.Equation (xParam R W hz) (yParam R W hz)

theorem isUnit_adicEval_wCofactor (W : WeierstrassCurve K) [IsIntegral R W] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) :
    IsUnit (adicEval (maximalIdeal R).asIdeal hz (integralModel R W).wCofactor)

theorem localParam_xParam_yParam (W : WeierstrassCurve K) [IsIntegral R W] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) (hz0 : z ≠ 0) :
    -xParam R W hz / yParam R W hz = algebraMap R K z

theorem wParam_eq_cube_mul (W : WeierstrassCurve K) [IsIntegral R W] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) :
    wParam R W hz = z ^ 3 * adicEval (maximalIdeal R).asIdeal hz (integralModel R W).wCofactor

theorem localParam_pointOfParam (W : WeierstrassCurve K) [IsIntegral R W] [W.IsElliptic] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) (hz0 : z ≠ 0) :
    localParam R W (pointOfParam R W hz hz0) = algebraMap R K z

theorem one_lt_valuation_xParam (W : WeierstrassCurve K) [IsIntegral R W] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) (hz0 : z ≠ 0) :
    1 < valuation K (maximalIdeal R) (xParam R W hz)

theorem reducesToZero_pointOfParam (W : WeierstrassCurve K) [IsIntegral R W] [W.IsElliptic] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) (hz0 : z ≠ 0) :
    ReducesToZero R W (pointOfParam R W hz hz0)

theorem zParam_pointOfParam (W : WeierstrassCurve K) [IsIntegral R W] [W.IsElliptic] {z : R}
    (hz : z ∈ (maximalIdeal R).asIdeal) (hz0 : z ≠ 0) :
    zParam R W ⟨pointOfParam R W hz hz0, reducesToZero_pointOfParam R W hz hz0⟩ = ⟨z, hz⟩

theorem wLineOne_mem (W : WeierstrassCurve K) [IsIntegral R W] {z₁ z₂ : R}
    (ha : ∀ s : Fin 2, ![z₁, z₂] s ∈ (maximalIdeal R).asIdeal) :
    wLineOne R W ha ∈ (maximalIdeal R).asIdeal

theorem wLineZero_mem (W : WeierstrassCurve K) [IsIntegral R W] {z₁ z₂ : R}
    (ha : ∀ s : Fin 2, ![z₁, z₂] s ∈ (maximalIdeal R).asIdeal) :
    wLineZero R W ha ∈ (maximalIdeal R).asIdeal

theorem redPt_add_of_Y_eq (W : WeierstrassCurve K) [HasGoodReduction R W]
    {x₁ y₁ : K} {h₁ : W.toAffine.Nonsingular x₁ y₁}
    {x₂ y₂ : K} {h₂ : W.toAffine.Nonsingular x₂ y₂}
    (hx : x₁ = x₂) (hy : y₁ = W.toAffine.negY x₂ y₂) :
    redPt R W (.some x₁ y₁ h₁ + .some x₂ y₂ h₂) = 0

theorem card_nsmul_eq_zero_directSum {ι : Type*} [Fintype ι]
    (B : ι → Type*) [∀ i, AddCommGroup (B i)] (q : ℕ) :
    Nat.card {d : ⨁ i, B i // q • d = 0} = ∏ i, Nat.card {x : B i // q • x = 0}

lemma card_setOf_equation_eq_two_of_isSquare (h2 : (2 : F) ≠ 0) {x : F}
    (hx : W.Ψ₂Sq.eval x ≠ 0) (hsq : IsSquare (W.Ψ₂Sq.eval x)) :
    Nat.card {y : F // W.Equation x y} = 2

theorem exists_nsmul_eq_some_of_hasXCoordFormula_of_root [W.IsElliptic] {n : ℕ}
    (hroot : ∀ x : F, (W.ΨSq n).eval x = 0 → (W.Φ n).eval x ≠ 0)
    (hform : HasXCoordFormula W n) {x₀ y₀ : F} (hQ : W.Nonsingular x₀ y₀) {x y : F}
    (hxy : W.Equation x y) (hx : (W.Φ n).eval x = x₀ * (W.ΨSq n).eval x) :
    ∃ P : W.Point, n • P = Point.some x₀ y₀ hQ

theorem exists_nsmul_eq_of_mem_torsion {ℓ : ℕ}
    (hℓ : Function.Surjective fun P : W.Point => ℓ • P) {k : ℕ} {y : W.Point}
    (hy : y ∈ W.torsion (ℓ ^ k)) : ∃ x ∈ W.torsion (ℓ ^ (k + 1)), ℓ • x = y

theorem nsmul_fst_of_closure {n : ℕ} {P Q : W.Point}
    (hgen : AddSubgroup.closure ({P, Q} : Set W.Point) = W.torsion n) :
    n • P = 0

theorem nsmul_snd_of_closure {n : ℕ} {P Q : W.Point}
    (hgen : AddSubgroup.closure ({P, Q} : Set W.Point) = W.torsion n) :
    n • Q = 0

theorem card_torsion_mul_of_surjective {p : ℕ}
    (hsurj : Function.Surjective fun P : W.Point => p • P) (n : ℕ) :
    Nat.card (W.torsion (n * p)) = Nat.card (W.torsion p) * Nat.card (W.torsion n)

theorem card_torsion_pow_of_surjective {p : ℕ}
    (hsurj : Function.Surjective fun P : W.Point => p • P) (k : ℕ) :
    Nat.card (W.torsion (p ^ k)) = Nat.card (W.torsion p) ^ k
